export type AiuxFieldPlain = {
    value: string;
};
export type AiuxFieldCdata = {
    isCdata: true;
    value: string;
};
export type AiuxFieldRef = {
    isRef: true;
    table: string;
    nowIdKey?: string;
    explicitSysId?: string;
};
export type AiuxFieldArray = {
    values: string[];
};
export type AiuxFieldValue = AiuxFieldPlain | AiuxFieldCdata | AiuxFieldRef | AiuxFieldArray;
export type AiuxRecordMetadata = {
    table?: string;
    fields: Record<string, AiuxFieldValue>;
    nowIdKey: string;
    uniqueKey: string;
    explicitSysId?: string;
    sysIdSourceKey?: string;
    demo_install: boolean;
    sourceFiles: string[];
    fluentPlugin?: string | null;
};
